ildren": [{"id": "cdfc6da0-1ed6-46fb-aef8-537eb384967b", "type": "subtopic", "title": "Reading and listening to authentic media", "children": [{"id": "abee3fdb-69c6-40c9-bbaa-65670624d66b", "type": "concept", "title": "Main idea and detail"}, {"id": "735a41d8-e468-4900-8abe-0cc56f0f4bcc", "type": "concept", "title": "Bias and framing"}, {"id": "b81a9eb0-eedb-4a7c-b01a-9956b71751ed", "type": "concept", "title": "Vocabulary harvesting"}, {"id": "38e53af3-c4b0-483b-8f39-b72fe53de835", "type": "concept", "title": "Transcript-based listening"}], "description": "Students use journalism, podcasts, interviews, and video as inputs for discussion and writing."}, {"id": "6153799b-28c5-49ea-b130-48ef9ffbf0c6", "type": "subtopic", "title": "Source evaluation", "children": [{"id": "912a85e9-64ad-4175-87bd-0794daebcdac", "type": "concept", "title": "Author and publication"}, {"id": "256a71c3-577e-4903-a46a-2d74ab94db3c", "type": "concept", "title": "Audience and purpose"}, {"id": "df61963d-ec2f-4176-857d-d0bbbb7823fa", "type": "concept", "title": "Evidence quality"}, {"id": "127d007f-c001-493d-9948-47199e991a7c", "type": "concept", "title": "Fact, opinion, and interpretation"}], "description": "This subtopic helps students judge credibility and context in Spanish-language sources."}, {"id": "576edc36-d741-4ca6-8c18-06ab553509db", "type": "subtopic", "title": "Integrating sources", "children": [{"id": "5bf06d6f-a3fd-4004-baf3-60a81bba1cc4", "type": "concept", "title": "Summary"}, {"id": "964b862e-afcd-45d7-913b-027e9d94b51d", "type": "concept", "title": "Paraphrase"}, {"id": "7dcb762e-929f-4107-a60c-eeee97b8140c", "type": "concept", "title": "Signal phrases"}, {"id": "eee0d68a-913f-43c2-b3f5-5ffd90f58d62", "type": "concept", "title": "MLA-style citation basics"}], "description": "Students learn to summarize, paraphrase, quote, and cite source material in Spanish."}]}, {"id": "399890dd-8778-4839-b6c8-aa946383dd7f", "type": "topic", "title": "Portfolio of Revised Writing and Speaking", "description": "The capstone topic asks students to gather evidence of growth, revise strategically, and reflect on their development as Spanish communicators.", "children": [{"id": "e5f7d049-66d8-4b4c-af5d-8ba7b6a07027", "type": "subtopic", "title": "Portfolio selection", "children": [{"id": "6a246d1a-b7bd-4611-adf9-5c44d973822a", "type": "concept", "title": "Narrative draft"}, {"id": "95d13f7a-094e-4aec-836a-ecf1c5c3035c", "type": "concept", "title": "Argumentative essay"}, {"id": "af277bae-3d3d-40d2-bfa5-76292d3989e5", "type": "concept", "title": "Presentation notes"}, {"id": "1747f2b9-66a5-4da0-a4a3-d87b698dbbf9", "type": "concept", "title": "Recorded speaking sample"}], "description": "Students choose artifacts that show range across modes and genres."}, {"id": "3a7f9d32-ad2c-44d5-ad63-f6c6c72a4ddf", "type": "subtopic", "title": "Reflective self-assessment", "children": [{"id": "b9632711-1e3d-4a85-9ae9-817aa3de307d", "type": "concept", "title": "Strengths"}, {"id": "ae1c10fe-8209-4f5c-a557-c0c9d93e8448", "type": "concept", "title": "Recurring errors"}, {"id": "939fbec9-25e9-4a8c-9462-4f793c76ca25", "type": "concept", "title": "Fluency goals"}, {"id": "3019e703-d025-44a4-b94b-0b8e4b4562d8", "type": "concept", "title": "Revision rationale"}], "description": "This subtopic helps students name what improved and what still needs work."}, {"id": "d1de0874-873e-445c-8cd1-27441b2448a3", "type": "subtopic", "title": "Final polish and presentation", "children": [{"id": "2082fb83-12a7-43d7-bb9d-0777f3325c93", "type": "concept", "title": "Clean formatting"}, {"id": "bc052eb5-7ed1-4a8b-8c4d-675571eb2919", "type": "concept", "title": "Final edits"}, {"id": "2caf12e7-be6c-4aa4-ba11-e7c85a3a6ee7", "type": "concept", "title": "Oral defense or conference"}, {"id": "d258887a-f6e4-4f2c-a922-a69b997c13e4", "type": "concept", "title": "Learning plan for next course"}], "description": "Students prepare a professional final submission."}]}], "dbBacked": true}$scccjson$::jsonb,
