update public.learning_paths
set
  title = 'Spanish Conversation and Composition',
  goal = 'Spanish Conversation and Composition',
  summary = 'This course develops advanced-intermediate to advanced Spanish communication through sustained conversation, process-based composition, pronunciation refinement, public speaking, debate, and culturally grounded inquiry. Students practice Spanish as a tool for interpersonal exchange, academic writing, public presentation, and informed discussion of the Spanish-speaking world. The course emphasizes fluency, accuracy, register, revision, and rhetorical control. Students produce a portfolio of revised writing and recorded speaking that demonstrates growth across narrative, expository, argumentative, and source-based genres.',
  data = $scccjson${"slug": "spanish-conversation-and-composition", "title": "Spanish Conversation and Composition", "description": "This course develops advanced-intermediate to advanced Spanish communication through sustained conversation, process-based composition, pronunciation refinement, public speaking, debate, and culturally grounded inquiry. Students practice Spanish as a tool for interpersonal exchange, academic writing, public presentation, and informed discussion of the Spanish-speaking world. The course emphasizes fluency, accuracy, register, revision, and rhetorical control. Students produce a portfolio of revised writing and recorded speaking that demonstrates growth across narrative, expository, argumentative, and source-based genres.", "topics": [{"id": "69091a79-a78e-4214-a38a-d78f38e68d2c", "type": "topic", "title": "Conversation Strategies", "description": "This topic develops the practical habits that let students sustain conversation, negotiate meaning, and participate confidently in Spanish beyond scripted exchanges.", "children": [{"id": "29988274-5d45-415c-9610-cc2e1939ae3c", "type": "subtopic", "title": "Maintaining interaction", "children": [{"id": "e63fdb15-ab24-4d0d-b938-0b9d6c372bbe", "type": "concept", "title": "Turn-taking"}, {"id": "677e6fc0-108a-4b28-8def-f1e1dd7752cf", "type": "concept", "title": "Follow-up questions"}, {"id": "6a6ce9d3-6481-4df3-8a6e-97254323453d", "type": "concept", "title": "Clarification and repair"}, {"id": "dcc0b3bd-82c3-46f2-a2f4-3aa302e17a67", "type": "concept", "title": "Circumlocution"}], "description": "Students learn how to keep a conversation moving even when vocabulary or grammar is imperfect."}, {"id": "4465276e-5f3a-40ee-8b9f-28833e0d760d", "type": "subtopic", "title": "Active listening", "children": [{"id": "784bdd11-532c-41ba-a73c-b029e45514d1", "type": "concept", "title": "Back-channeling"}, {"id": "f4997889-7cbb-4904-902a-d2951fb29259", "type": "concept", "title": "Summarizing a partner's point"}, {"id": "5a31ccc7-836d-4557-9708-a88a16d13706", "type": "concept", "title": "Checking comprehension"}, {"id": "70399ead-9ae8-4ca1-a26a-a754f5defb20", "type": "concept", "title": "Responding to tone"}], "description": "This subtopic emphasizes listening as a visible conversational skill, not a passive activity."}, {"id": "2700bf44-135c-4abd-86b8-b1f54b97b95d", "type": "subtopic", "title": "Spontaneous speech", "children": [{"id": "79523fc2-6c51-4da3-90fb-7d0411cb6261", "type": "concept", "title": "Timed speaking"}, {"id": "dba45f51-53b1-4d70-ac69-67daac0b97b7", "type": "concept", "title": "Impromptu responses"}, {"id": "b07ac515-c11c-4121-bf0f-e038e4de887a", "type": "concept", "title": "Story prompts"}, {"id": "55f51072-ce09-4ed1-a7c5-7baf0c398f2a", "type": "concept", "title": "Conversation circles"}], "description": "Students practice speaking with fluency, flexibility, and appropriate risk-taking."}]}, {"id": "80f2d616-ad28-4fbf-8d64-375a82ab6de7", "type": "topic", "title": "Pronunciation and Fluency Workshop", "description": "Pronunciation work helps students become more comprehensible, expressive, and aware of variation across the Spanish-speaking world.", "children": [{"id": "ecfd1115-a116-49ef-9e1f-b5b8ddbd4fff", "type": "subtopic", "title": "Segmental accuracy", "children": [{"id": "d1b676b2-5b7a-4ea9-9b29-7f94100b9410", "type": "concept", "title": "Vowels"}, {"id": "437f7bad-286a-4aad-ad2d-6e159939b273", "type": "concept", "title": "Taps and trills"}, {"id": "3aea3063-afca-410a-8f9e-b9d7bebd1148", "type": "concept", "title": "B and v"}, {"id": "154ad5bb-d646-491b-bf42-2fa551cdfcbf", "type": "concept", "title": "D, g, j, ll, y, s, z, and c variation"}], "description": "Students refine individual sounds that affect clarity and listener comprehension."}, {"id": "4fabe2b0-5612-404d-ae07-e47970a36c90", "type": "subtopic", "title": "Prosody and rhythm", "children": [{"id": "f0038023-c4ea-4318-9310-459f844b3696", "type": "concept", "title": "Stress patterns"}, {"i